// Patches the platform folders generated by `flutter create`.
// Adds Android network permissions and sets the display name "NetScan".
// Safe to run multiple times:  dart run tool/patch_platforms.dart
import 'dart:io';

void patch(String path, String Function(String) change) {
  final f = File(path);
  if (!f.existsSync()) return;
  final before = f.readAsStringSync();
  final after = change(before);
  if (after != before) {
    f.writeAsStringSync(after);
    stdout.writeln('patched $path');
  }
}

void main() {
  patch('android/app/src/main/AndroidManifest.xml', (s) {
    const perms = [
      'android.permission.INTERNET',
      'android.permission.ACCESS_NETWORK_STATE',
      'android.permission.ACCESS_WIFI_STATE',
      'android.permission.CHANGE_WIFI_MULTICAST_STATE',
      'android.permission.ACCESS_FINE_LOCATION',
      'android.permission.ACCESS_COARSE_LOCATION',
    ];
    final block = perms
        .where((p) => !s.contains(p))
        .map((p) => '    <uses-permission android:name="$p"/>\n')
        .join();
    if (block.isNotEmpty) {
      final m = RegExp(r'<manifest[^>]*>\s*\n').firstMatch(s);
      if (m != null) s = s.replaceRange(m.end, m.end, block);
    }
    return s.replaceFirst(
        RegExp(r'android:label="[^"]*"'), 'android:label="NetScan"');
  });

  // Native Wi-Fi channel (SSID, signal, band...).
  final kt = File('tool/android/MainActivity.kt');
  final ktDir = Directory('android/app/src/main/kotlin/ro/netscan/netscan');
  if (kt.existsSync() && ktDir.existsSync()) {
    kt.copySync('${ktDir.path}/MainActivity.kt');
    File('tool/android/NetScanWidget.kt').copySync('${ktDir.path}/NetScanWidget.kt');
    stdout.writeln('copied MainActivity.kt + NetScanWidget.kt');
  }

  // Home-screen widget resources.
  final resSrc = Directory('tool/android/res');
  final resDst = Directory('android/app/src/main/res');
  if (resSrc.existsSync() && resDst.existsSync()) {
    for (final f in resSrc.listSync(recursive: true).whereType<File>()) {
      final rel = f.path.substring(resSrc.path.length + 1);
      final out = File('${resDst.path}/$rel');
      out.parent.createSync(recursive: true);
      f.copySync(out.path);
    }
    stdout.writeln('copied widget resources');
  }
  patch('android/app/src/main/AndroidManifest.xml', (s) {
    if (s.contains('.NetScanWidget')) return s;
    const receiver = '''
        <receiver android:name=".NetScanWidget" android:exported="false" android:label="NetScan">
            <intent-filter>
                <action android:name="android.appwidget.action.APPWIDGET_UPDATE" />
            </intent-filter>
            <meta-data android:name="android.appwidget.provider"
                android:resource="@xml/netscan_widget_info" />
        </receiver>
    ''';
    return s.replaceFirst('</application>', '$receiver</application>');
  });

  patch('windows/runner/main.cpp', (s) => s
      .replaceAll('L"netscan"', 'L"NetScan"')
      .replaceAll('Win32Window::Size size(1280, 720);',
          'Win32Window::Size size(1280, 820);'));

  patch('windows/runner/Runner.rc', (s) => s
      .replaceAll('"FileDescription", "netscan"', '"FileDescription", "NetScan"')
      .replaceAll('"ProductName", "netscan"', '"ProductName", "NetScan"')
      .replaceAll('"InternalName", "netscan"', '"InternalName", "NetScan"'));

  patch('windows/CMakeLists.txt',
      (s) => s.replaceAll('set(BINARY_NAME "netscan")', 'set(BINARY_NAME "NetScan")'));
}
